INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish10', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3347,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket materiale 'leder' elektrisk strøm godt?","o":["gummi","glas","plastik","kobber"],"a":"kobber","r":"Metaller som kobber lader strømmen løbe let igennem. Derfor er ledninger lavet af kobber og pakket ind i plastik."},
{"l":3370,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes den vigtigste lov i Danmark, som fastlægger, hvordan landet skal styres?","o":["Grundloven","Straffeloven","Færdselsloven","Folkeskoleloven"],"a":"Grundloven","r":"Grundloven er grundlaget for alle andre love. Den første danske grundlov er fra 1849."},
{"l":3388,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi har mistet Pelle! Han er et lille, brunt marsvin med en hvid plet på næsen. Han slap ud af sit bur i 3.C i går. Han elsker agurk. Hvis du ser ham, så kald ikke højt, men hent en voksen, for han bliver let bange.' Hvorfor skal man ikke kalde højt?","o":["Fordi der er undervisning i 3.C i dag","Fordi Pelle så kan blive bange og løbe","Fordi Pelle ikke kan høre sit navn","Fordi han kun kommer, hvis man har agurk"],"a":"Fordi Pelle så kan blive bange og løbe","r":"Der står, at han let bliver bange. Man kan slutte, at høje råb kan skræmme ham væk."},
{"l":3410,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordsleddet: 'Hesten står i stalden.'","o":["Hesten","står","i stalden","Hesten står"],"a":"i stalden","r":"Et forholdsordsled består af et forholdsord og det, der følger efter det. Her er det 'i' plus 'stalden'."},
{"l":3432,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Anton havde bygget et tårn af klodser, der næsten nåede loftet. Lillesøster stod ved siden af og ville så gerne lægge den sidste klods. Anton så på tårnet, så på klodsen i sin hånd og så på hendes små fingre. Længe stod han og vendte klodsen.' Hvad overvejer Anton nok?","o":["Om tårnet kan nå helt op til loftet","Om han skal bygge et nyt tårn et andet sted","Om klodsen har den rigtige farve til tårnet","Om han skal lade lillesøster lægge den sidste klods"],"a":"Om han skal lade lillesøster lægge den sidste klods","r":"Lillesøster vil gerne lægge klodsen, men tårnet er højt, og hendes fingre er små. Derfor tøver Anton med klodsen i hånden."},
{"l":3452,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"En 'snarrådig' pige fik slukket ilden i gryden. Hvordan var hun?","o":["Hun fandt hurtigt på en god løsning","Hun var meget bange for ild og røg","Hun ventede længe, før hun gjorde noget","Hun løb ud og råbte på sin mor"],"a":"Hun fandt hurtigt på en god løsning","r":"Snarrådig betyder, at man hurtigt ved, hvad man skal gøre, når noget uventet sker."},
{"l":3470,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem siges at have fortalt mange af de kendte fabler i det gamle Grækenland?","o":["Homer","Æsop","Platon","Cæsar"],"a":"Æsop","r":"Fablerne om ræven og ravnen og om haren og skildpadden kaldes Æsops fabler. Navnet skrives også Aisopos."},
{"l":3490,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket af disse dyr er en 'parasit'?","o":["regnorm","musvit","flåt","honningbi"],"a":"flåt","r":"En parasit lever på eller i et andet dyr og skader det. Flåten suger blod af sin vært."},
{"l":3509,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led er 'bolden' i sætningen: 'Oskar sparkede bolden langt væk.'","o":["grundled","udsagnsled","hensynsled","genstandsled"],"a":"genstandsled","r":"Spørg: Hvad sparkede Oskar? Bolden er det, handlingen går ud over, og det er et genstandsled."},
{"l":3531,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Jeg holder fødselsdag for mine bedste ___.'","o":["venner","vener","vænner","venne"],"a":"venner","r":"Ental er 'ven'. N'et fordobles i flertal, fordi e'et er kort. Med ét n handler ordet om blodårer."},
{"l":3549,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Månen lyser ikke selv. Det, vi ser, er sollys, der bliver kastet tilbage fra månens overflade. Når månen kredser om Jorden, ser vi skiftevis mere og mindre af dens oplyste side. Derfor ser den ud til at skifte form hen over måneden.' Hvad er grunden til, at månen ser ud til at skifte form?","o":["Den bliver større og mindre i løbet af måneden","Vi ser forskellige dele af dens oplyste side","Skyerne dækker den i perioder af måneden","Den ændrer sin farve hen over måneden"],"a":"Vi ser forskellige dele af dens oplyste side","r":"Månen ændrer sig ikke selv. Det, der ændrer sig, er hvor meget af den oplyste side vi kan se."},
{"l":3568,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Til Jul besøger Freja sin moster i Svendborg.'?","o":["Til","Freja","Jul","Svendborg"],"a":"Jul","r":"Højtider skrives med lille, så der skal stå 'jul'. 'Til' står først, og Freja og Svendborg er navne."},
{"l":3587,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder endelsen '-løs' i 'hjælpeløs' og 'arbejdsløs'?","o":["med","meget","næsten","uden"],"a":"uden","r":"Den hjælpeløse er uden hjælp, og den arbejdsløse er uden arbejde."},
{"l":3608,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Alle ___ og fædre var inviteret til sommerfesten.'","o":["mødre","møder","mødrer","mødere"],"a":"mødre","r":"Flertal af 'mor' er uregelmæssigt og ender på -dre uden r til sidst."},
{"l":3625,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvornår er ordsproget 'Man skal ikke sælge skindet, før bjørnen er skudt' en god advarsel?","o":["Når nogen vil købe en dyr vinterjakke i butikken","Når nogen regner med noget, der ikke er sikkert","Når nogen vil tage ud at se vilde dyr i skoven","Når nogen sælger sine ting for billigt til andre"],"a":"Når nogen regner med noget, der ikke er sikkert","r":"Ordsproget advarer mod at regne med gevinsten, før man har den. Holdet har for eksempel ikke vundet, før kampen er slut."},
{"l":3647,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Da Bo kom for sent, 'stak han læreren en plade'. Hvad gjorde han?","o":["Han gav en ærlig undskyldning","Han afleverede sit projekt","Han fandt på en løgn","Han rakte læreren en tallerken"],"a":"Han fandt på en løgn","r":"At stikke nogen en plade er at bilde dem noget ind, altså at lyve for at slippe let."},
{"l":3663,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Husk disse ting til turen___ madpakke, regntøj og gode sko.'?","o":["semikolon","punktum","spørgsmålstegn","kolon"],"a":"kolon","r":"Kolon viser, at nu kommer de ting, man skal huske. Ordene efter tegnet står med lille, så sætningen er ikke slut."},
{"l":3685,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Bussen ___ brat for rødt lys i går.'","o":["stoppede","stopede","stoppet","stoppte"],"a":"stoppede","r":"Datid af 'stoppe' ender på -ede, og p'et er dobbelt, fordi o'et er kort."},
{"l":3707,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find ledsætningen: 'Vi spiser, når far kommer hjem.'","o":["Vi spiser","når far kommer hjem","far kommer hjem","Vi spiser, når far"],"a":"når far kommer hjem","r":"Ledsætningen begynder med bindeordet 'når' og kan ikke stå alene. 'Vi spiser' er hovedsætningen."},
{"l":3727,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ingrid havde vundet klassens stavekonkurrence tre år i træk. I år stod hun over for en ny dreng, Hamza, som kun havde boet i Danmark i to år. Da ordet ræverød var det sidste, stavede Hamza det rigtigt, og Ingrid mærkede, at hun blev varm i kinderne. Så rejste hun sig og gav ham hånden.' Hvad viser Ingrids handling?","o":["Hun tror, at Hamza har snydt med stavningen","Hun vil have konkurrencen spillet om igen","Hun er skuffet, men kan godt tåle at tabe","Hun er ligeglad med at have tabt konkurrencen"],"a":"Hun er skuffet, men kan godt tåle at tabe","r":"De varme kinder viser, at hun er skuffet, og håndtrykket viser, at hun kan tåle at tabe."},
{"l":3745,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lørdag åbner Vesterhavets Sælcenter igen efter ombygningen. Centeret har haft lukket i et halvt år, fordi bassinet var utæt. Nu er der plads til flere syge sæler. Lederen, Birthe Lund, siger: – Vi tager imod omkring 30 sælunger om året, og de har brug for ro og rent vand.' Hvorfor havde centeret lukket?","o":["Der skulle være plads til flere syge sæler","Sælungerne havde brug for mere ro","Der var for mange gæster om lørdagen","Bassinet skulle laves, fordi det var utæt"],"a":"Bassinet skulle laves, fordi det var utæt","r":"Det står direkte, at centeret havde lukket, fordi bassinet var utæt."},
{"l":3763,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Gutenberg udviklede omkring år 1450 en trykpresse med løse bogstaver af metal. Før den tid blev bøger skrevet af i hånden, og det tog måneder. Nu kunne man lave mange ens bøger på kort tid. Bøger blev billigere, og flere mennesker lærte at læse.' Hvad var en følge af trykpressen?","o":["Flere mennesker fik adgang til bøger","Det tog længere tid at lave bøger end før","Bøger blev kun lavet til de rigeste folk","Folk holdt helt op med at skrive i hånden"],"a":"Flere mennesker fik adgang til bøger","r":"Billigere bøger og flere læsere var virkningen af, at man kunne trykke mange bøger på kort tid."},
{"l":3784,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Flasken ___ en halv liter saft.'","o":["rumer","rummer","rommer","rummerer"],"a":"rummer","r":"U'et er kort, så m'et er dobbelt. Nutid ender på -er."},
{"l":3806,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form er den rigtige? 'Hvem ___, hvad vi skal lege i frikvarteret?'","o":["bestemer","bestæmmer","bestemmer","bestemmerer"],"a":"bestemmer","r":"Trykket ligger på vokalen foran m, som er kort, så m'et er dobbelt."},
{"l":3826,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alle på vejen vidste, at hr. Dahl var sur. Han råbte ad børnene, når bolden landede i hans have. Men en dag fandt Mads bolden liggende på sin dørmåtte, pumpet op og lappet. Dagen efter så han hr. Dahl stå bag gardinet og kigge på deres spil med et lille smil.' Hvad viser teksten om hr. Dahl?","o":["At han helst vil have boldspillet stoppet","At han vil købe en ny bold til Mads","At han vil klage over børnenes spil","At han er sødere, end folk tror"],"a":"At han er sødere, end folk tror","r":"Først virker han sur, men han lapper bolden og smiler bag gardinet. Folk har taget fejl af ham."},
{"l":3844,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Et isbjergs største del er under vandet. Over vandet ser man kun cirka en tiendedel. Derfor var isbjerge farlige for skibe i gamle dage, for de kunne ramme is, de ikke kunne se. I dag bruger man radar og satellitter til at finde dem.' Hvorfor er isbjerge mindre farlige for skibe nu end i gamle dage?","o":["Skibene finder dem med radar og satellitter","Skibene sejler kun, hvor der ikke er is","Isbjergene er blevet meget mindre end før","Nu ligger det meste af isen over vandet"],"a":"Skibene finder dem med radar og satellitter","r":"I gamle dage kunne skibene ramme is, de ikke kunne se. I dag finder man isbjergene med radar og satellitter. Det meste af isen ligger stadig under vandet."},
{"l":3862,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Efter en storm i januar blev der fundet flere hundrede kilo plastiklegetøj på stranden ved Hvidbjerg. Det stammede fra en container, der var faldet af et skib. Kommunens folk har ryddet stranden, men man finder stadig små stykker. Containerskibets ejer har lovet at betale for oprydningen.' Hvorfor kom plastiklegetøjet på stranden?","o":["Kommunen havde smidt det ud ved stranden","En container var faldet af et skib","Turister havde glemt det efter sommeren","Stormen havde blæst det fra en butik"],"a":"En container var faldet af et skib","r":"Der står, at legetøjet stammer fra en container. Stormen er den situation, fundet skete i."},
{"l":3883,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Bedstemor har ___ den historie mange gange.'","o":["fortalte","fortæller","fortalt","fortælle"],"a":"fortalt","r":"'Har' skal følges af tillægsform. 'Fortalte' er datid og hører ikke til efter 'har'."},
{"l":3902,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ordet 'demokrati' kommer fra græsk. Hvad betyder det på dansk?","o":["kongestyre","præstestyre","hærstyre","folkestyre"],"a":"folkestyre","r":"Demos betyder folk, og kratos betyder magt. I et demokrati vælger folket dem, der skal styre landet."},
{"l":3925,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Efter sin første sejr fik Noor 'blod på tanden'. Hvad betyder det?","o":["Hun fik lyst til at vinde mere","Hun slog sig under kampen","Hun blev vred på modstanderen","Hun skulle hen til tandlægen"],"a":"Hun fik lyst til at vinde mere","r":"Får man blod på tanden, bliver man ivrig efter mere, fordi det første gik godt."},
{"l":3940,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Det lynede. En skygge gled gennem gangen på det gamle slot. Døren knirkede.' Hvilken stemning er der i teksten?","o":["munter","uhyggelig","kedelig","fredelig"],"a":"uhyggelig","r":"Lyn, skygger og knirkende døre skaber uhygge. Forfatteren vælger netop de ord for at gøre læseren urolig."},
{"l":3961,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sneen faldt tæt uden for vinduet, og radiatoren knagede lidt. Hedda lå på gulvet med et tæppe om benene og en kop kakao ved siden af sig. Hunden sov på hendes fødder. Der var ikke nogen, der skulle noget i dag.' Hvad er stemningen i teksten?","o":["Spændt og uhyggelig","Kedelig og ensom","Rolig og hyggelig","Trist og kold"],"a":"Rolig og hyggelig","r":"Der er koldt udenfor, men Hedda ligger lunt med kakao og hund, og ingen skal noget. Det er roligt og hyggeligt."},
{"l":3982,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Hun fik en ___ ny cykel i rød lak.'","o":["skinende","skinnene","skinene","skinnende"],"a":"skinnende","r":"Ordet kommer af 'skinne' med dobbelt n, og lang tillægsform ender på -ende."},
{"l":4005,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'At du kom i dag glæder mig meget.'?","o":["dag","kom","glæder","mig"],"a":"dag","r":"'At du kom i dag' er en ledsætning, der står først og fungerer som grundled. Derfor skal der komma efter den."},
{"l":4024,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange ord mangler stort bogstav: 'om sommeren rejser familien til spanien, og i oktober besøger de ali i vejle.'?","o":["to","fire","tre","fem"],"a":"fire","r":"'om' står først i sætningen, og Spanien, Ali og Vejle er navne. Årstider og måneder som sommer og oktober skrives med lille."},
{"l":4045,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'tvetydigt' i sætningen: 'Hun gav et tvetydigt svar.'","o":["høfligt","forkert","entydigt","langsomt"],"a":"entydigt","r":"Et tvetydigt svar kan forstås på to måder. Et entydigt svar kan kun forstås på én måde."},
{"l":4062,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Et komma er sat forkert i én af sætningerne om skolevejen. Hvilken?","o":["Da vi gik hjem fra skole, mødte jeg en ven.","Jeg mødte Ali, Sara og Hassan.","Når skolen slutter, møder jeg en ven.","På vej hjem fra skole, mødte jeg en ven."],"a":"På vej hjem fra skole, mødte jeg en ven.","r":"'På vej hjem fra skole' har intet udsagnsord og er ikke en ledsætning. Derfor skal der ikke komma efter det."},
{"l":4081,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Pengene er Mikkels egne. Hvilket ord passer: 'Mikkel er ked af det, fordi han har tabt ___ penge.'","o":["sine","sin","sit","hans"],"a":"sine","r":"Ledsætningens grundled 'han' er ejeren, og 'penge' står i flertal. Derfor hedder det 'sine'."},
{"l":4103,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at bo' passer: 'Hele sidste uge ___ vi i sommerhuset.'","o":["boet","boede","bor","bo"],"a":"boede","r":"Her er der ikke noget 'har', så der skal bruges datid. 'Boet' er tillægsform."},
{"l":4122,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tang vokser i havet og har i Danmark mest været brugt som gødning eller dyrefoder. I Japan har man spist tang i hundreder af år. Nu vil flere danske forskere undersøge, om tang kan blive en almindelig fødevare her. Tang vokser hurtigt og kræver ingen marker.' Hvorfor er forskerne interesseret i tang?","o":["Fordi tang smager bedre end andre grøntsager","Fordi tang er godt som dyrefoder","Fordi tang kan dyrkes uden at bruge marker","Fordi tang er den eneste mad, der vokser i havet"],"a":"Fordi tang kan dyrkes uden at bruge marker","r":"Teksten slutter med tangs fordele: hurtig vækst og ingen brug for marker."},
{"l":4142,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en lille fugleunge er 'sårbar'?","o":["Den har allerede et sår på vingen","Den kan snart flyve helt selv","Den spiser mere end de voksne","Den kan let komme til skade"],"a":"Den kan let komme til skade","r":"Sårbar betyder, at man let kan blive såret eller skadet. Det betyder ikke, at man allerede er det."},
{"l":4158,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Find din hemmelige helt! Skolebiblioteket laver en udstilling om mennesker, der har hjulpet andre uden at blive kendt. Alle elever kan aflevere en lille tekst om en, de kender. Teksterne hænges op i uge 11. Bedste tekst vinder en boggave.' Hvad ønsker biblioteket, at eleverne skal skrive om?","o":["En person, der stille og roligt hjælper andre","Berømte personer fra historien","Deres egen yndlingshelt fra film og bøger","En hemmelighed, de aldrig har fortalt"],"a":"En person, der stille og roligt hjælper andre","r":"'Hemmelig helt' forklares i teksten som et menneske, der hjælper uden at blive kendt."},
{"l":4180,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led er 'mine nøgler' i sætningen: 'Jeg har tabt mine nøgler i sneen.'","o":["hensynsled","genstandsled","forholdsordsled","grundled"],"a":"genstandsled","r":"Spørg: Hvad har jeg tabt? Svaret er genstandsleddet. 'I sneen' er et forholdsordsled."},
{"l":4202,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad advarer ordsproget 'Man skal ikke kaste med sten, når man selv bor i et glashus' imod?","o":["At lege med sten tæt ved vinduer og ruder","At købe et hus, der er alt for dyrt at holde","At kritisere andre for det, man selv gør","At sige sin mening til nogen, man ikke kender"],"a":"At kritisere andre for det, man selv gør","r":"Den, der selv har fejl, er lige så sårbar som en, der bor bag glas. Derfor skal man ikke angribe andre for det samme."},
{"l":4221,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sidste år kom der 30 til vores sommerfest. I år var der over 200. Forskellen? Vi har holdt op med at hænge sedler op og er begyndt at gå rundt og invitere folk ansigt til ansigt. Folk vil gerne føle sig ønsket, siger formanden for beboerforeningen.' Hvad er forklaringen på, at flere kom?","o":["Sedlerne var bedre lavet i år end sidste år","Vejret var bedre, end det havde været før","Der var flere beboere i området i år","Folk var blevet inviteret personligt"],"a":"Folk var blevet inviteret personligt","r":"Formanden peger selv på forskellen: at invitere folk ansigt til ansigt i stedet for at bruge sedler."},
{"l":4239,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tak for kaffe, sagde Ella, da hun fik øje på regningen for den nye rude. Hendes bror havde sparket en bold gennem ruden, og nu skulle hun, som havde passet ham, betale halvdelen. Hun sendte ham et blik, som kunne have fået havet til at fryse.' Hvad betyder Tak for kaffe i denne sammenhæng?","o":["At det er en slem overraskelse","At hun gerne vil have kaffe","At hun vil gå hjem nu","At hun takker for hjælpen med ruden"],"a":"At det er en slem overraskelse","r":"Tak for kaffe siger man, når man får en slem overraskelse. Hendes vrede blik viser, at hun ikke mener tak."},
{"l":4257,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Forfatteren til bogen om pigen på Grønland har selv boet deroppe. Det kan man mærke på beskrivelserne af lys og sne. Slutningen er efter min smag lidt for hurtig. Men bogen fik mig til at ville vide mere om Grønland, og det er det bedste, man kan sige om en bog.' Hvad er skribentens samlede vurdering af bogen?","o":["Bogen er perfekt fra første side til den sidste","Bogen er god, selvom den har en svaghed","Bogen er kedelig, men handler om noget vigtigt","Bogen er god, men slutningen ødelægger den"],"a":"Bogen er god, selvom den har en svaghed","r":"Der er både ros og kritik, men rosen fylder mest, og den sidste sætning er tydeligt positiv."},
{"l":4279,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Vi spiste vores madpakker ___ til stranden.'","o":["underveis","undervæjs","undervejs","undervej"],"a":"undervejs","r":"Ordet skrives i ét, staves med ej og ender på s."},
{"l":4300,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Den gamle kastanje på torvet skulle fældes, stod der i avisen. Dagen efter hang der et skilt om stammen: Jeg har givet skygge i 120 år. Hvad har du givet? Ingen vidste, hvem der havde hængt det op. Men ugen efter kom der 500 underskrifter til byrådet.' Hvorfor virker skiltet så stærkt?","o":["Fordi det fortæller, præcis hvor gammelt træet er","Fordi det kommer fra byrådet selv","Fordi det beviser, at træet stadig er sundt","Fordi det er skrevet, som om træet selv taler"],"a":"Fordi det er skrevet, som om træet selv taler","r":"Når træet får en stemme og stiller et spørgsmål til læseren, bliver det personligt. Det får folk til at reagere."},
{"l":4322,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'da' i sætningen: 'Vi spiste færdig, og da var klokken allerede otte.'","o":["biord","bindeord","forholdsord","stedord"],"a":"biord","r":"Her betyder 'da' det samme som 'på det tidspunkt'. Det indleder ikke en ledsætning og er derfor et biord."},
{"l":4342,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad arbejdede H.C. Andersens far med?","o":["bager","skomager","præst","smed"],"a":"skomager","r":"H.C. Andersens far lavede og reparerede sko i Odense. Han læste også tit højt for sin søn."},
{"l":4363,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler? 'Efter turen bad læreren os ___ over, hvad vi havde lært.'","o":["repræsentere","reparere","reflektere","registrere"],"a":"reflektere","r":"At reflektere over noget er at tænke grundigt over det. De andre ord ligner, men betyder noget helt andet."},
{"l":4382,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Røgen fra brændeovnen stiger op gennem den. Hvilket ord er stavet rigtigt?","o":["skorstæn","skorstein","skårsten","skorsten"],"a":"skorsten","r":"Ordet ender på -sten, og der står r efter det første o, selvom man ikke altid hører det."},
{"l":4400,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kokosnødder kan flyde på havet i uger og alligevel spire på en fjern strand. Det er en af grundene til, at kokospalmer vokser på så mange afsides øer.' Hvilket spørgsmål besvarer teksten?","o":["Hvordan kan kokospalmer nå ud til fjerne øer?","Hvor høj kan en kokospalme blive i varme lande?","Hvor mange kokosnødder giver et træ om året?","Hvorfor smager kokosnødder forskelligt fra ø til ø?"],"a":"Hvordan kan kokospalmer nå ud til fjerne øer?","r":"Teksten forklarer spredningen via havet. Højde, antal og smag bliver slet ikke omtalt."},
{"l":4420,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'På Havneskolens nye app kan forældre følge med i, hvor deres barn er. Skolen siger, at det giver tryghed. Men 6.B har skrevet til skolelederen: Vi er ikke pakker, der skal spores. Eleverne foreslår, at man kun bruger appen på ture.' Hvad er uenigheden mellem skolen og 6.B?","o":["Hvor meget appen skal koste for forældrene","Om forældre hele tiden skal kunne se, hvor eleverne er","Hvor ofte eleverne må tage på ture med klassen","Om eleverne må have mobilen med i skole"],"a":"Om forældre hele tiden skal kunne se, hvor eleverne er","r":"Skolen siger, at appen giver tryghed, men eleverne vil ikke spores hele tiden. De vil kun bruge den på ture."},
{"l":4440,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'De frivillige i Lindby Fugleklub har i år hængt 800 redekasser op i byens skove. Kasserne er bygget i løbet af vinteren. Formand Inger Vestergaard siger, at der er flere fugle, end der har været længe, så der er brug for endnu flere kasser. Hun opfordrer flere til at melde sig som hjælpere, for gruppen er blevet ældre og færre.' Hvad er problemet for gruppen?","o":["Der er for få fugle i byens skove","Byens beboere vil ikke have kasser i skoven","De mangler hjælpere, nu hvor der skal bruges flere kasser","Træet til kasserne er blevet svært at få fat i"],"a":"De mangler hjælpere, nu hvor der skal bruges flere kasser","r":"Der skal bruges flere kasser, men gruppen bliver ældre og mindre. Derfor beder formanden flere om at melde sig."},
{"l":4460,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Afsenderen af en tekst vil altid noget med sin tekst. Det kan være at oplyse, underholde eller overtale. En nyhed skal oplyse, og en reklame skal overtale. Men nogle tekster ligner en nyhed og er i virkeligheden reklame. Derfor skal man altid spørge: Hvem har skrevet det, og hvad vil de?' Hvad er teksten en opfordring til?","o":["At læse flere nyheder i løbet af ugen","At undgå at læse reklamer helt og aldeles","At skrive sine egne tekster til avisen","At tænke over, hvem der har skrevet det, man læser"],"a":"At tænke over, hvem der har skrevet det, man læser","r":"Slutningen siger, at man altid skal spørge, hvem der har skrevet teksten, og hvad de vil. Det er at læse kritisk."},
{"l":4480,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken dato er skrevet rigtigt i invitationen til Yusufs fødselsdag?","o":["den 14. marts","den 14 marts","den 14, marts","den 14: marts"],"a":"den 14. marts","r":"Datoen er et ordenstal, 'den fjortende', og ordenstal skrevet med tal får punktum."},
{"l":4499,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'På Mandag skal Ali til Aarhus med Nadia.'?","o":["Ali","Mandag","Aarhus","Nadia"],"a":"Mandag","r":"Ugedage skrives med lille på dansk. Personnavne og bynavne skrives med stort."},
{"l":4518,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket mål er skrevet rigtigt, når en snor er tre en halv meter lang?","o":["3.5 meter","3:5 meter","3,5 meter","3'5 meter"],"a":"3,5 meter","r":"På dansk skriver man decimaltal med komma. Punktum i tal bruges til at adskille tusinder."},
{"l":4537,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om cykelturen i skoven har ingen overflødige kommaer?","o":["Efter skole, cyklede vi en tur i skoven.","Efter skole cyklede vi, en tur i skoven.","Efter skole cyklede, vi en tur i skoven.","Efter skole cyklede vi en tur i skoven."],"a":"Efter skole cyklede vi en tur i skoven.","r":"'Efter skole' er ikke en ledsætning, for der er intet udsagnsled i det. Derfor skal der ikke komma."},
{"l":4558,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Bedstefar er gået på 'pension'. Hvad betyder det?","o":["han er stoppet med at arbejde på grund af sin alder","han er flyttet ind på et lille hotel ved stranden","han er blevet ansat i et nyt firma i nærheden","han er rejst på en lang ferie sammen med venner"],"a":"han er stoppet med at arbejde på grund af sin alder","r":"Når man går på pension, holder man op med at arbejde og får penge at leve for. Et pensionat er derimod et lille hotel."},
{"l":4575,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at følge': 'I går ___ vi stien hele vejen ned til søen.'","o":["fulgt","fulgte","følger","følge"],"a":"fulgte","r":"'I går' kræver datid. 'At følge' bøjes følger, fulgte, har fulgt."},
{"l":4597,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"I hvilken sætning betyder 'ret' det samme som 'ganske'?","o":["Min yndlingsret er lasagne.","Du har ret i det, du siger.","Filmen var ret spændende.","Alle har ret til at gå i skole."],"a":"Filmen var ret spændende.","r":"Foran et tillægsord betyder 'ret' ganske eller temmelig. Ordet kan også betyde en madret, at være korrekt eller en rettighed."},
{"l":4612,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord giver mening? 'Politiet ___ sagen og talte med flere vidner.'","o":["efterlignede","eftersendte","afskaffede","efterforskede"],"a":"efterforskede","r":"At efterforske er at undersøge en sag for at finde ud af, hvad der er sket. Det er politiets arbejde."},
{"l":4632,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvorfor står der komma i 'Selvom det var koldt, badede vi.'?","o":["Fordi en ledsætning slutter der","Fordi det er en opremsning","Fordi nogen bliver tiltalt","Fordi der kommer direkte tale"],"a":"Fordi en ledsætning slutter der","r":"'Selvom det var koldt' er en ledsætning. Når den er slut, skal der komma, inden sætningen fortsætter."},
{"l":4652,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'så' i sætningen: 'Først spiste vi, og så gik vi hjem.'","o":["bindeord","biord","udsagnsord","forholdsord"],"a":"biord","r":"'Så' betyder her 'bagefter' og fortæller, hvornår vi gik hjem. Det er 'og', der binder sætningerne sammen, så 'så' er et biord."},
{"l":4672,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'ord' i sætningen 'Jeg giver dig mit ord på, at jeg kommer'?","o":["et råd","en undskyldning","et løfte","en forklaring"],"a":"et løfte","r":"At give sit ord er at love noget. Derfor siger man også, at man holder sit ord."},
{"l":4694,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Bonden blev ___, da køerne for tredje gang løb ud af folden.'","o":["rassende","rasene","rasenne","rasende"],"a":"rasende","r":"Lang tillægsform ender på -ende. S'et er enkelt, fordi a'et er langt."},
{"l":4706,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Den ___ sol fik os til at søge skygge.'","o":["brændende","brændene","brænnende","brændenne"],"a":"brændende","r":"Ordet kommer af 'brænde', så der skal d både før og i endelsen -ende."},
{"l":4725,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I oldtiden troede mange, at Jorden var flad. Men allerede for over 2.000 år siden regnede grækeren Eratosthenes Jordens omkreds ud. Han sammenlignede solens skygger i to byer og kom meget tæt på det rigtige tal. Han havde hverken satellit eller fly, kun sine øjne, solen og sin hjerne.' Hvad vil den sidste sætning understrege?","o":["At han gættede sig til tallet uden at regne","At det var flot klaret med så få hjælpemidler","At satellitter ikke kan bruges til at måle Jorden","At han havde bedre øjne end andre mennesker"],"a":"At det var flot klaret med så få hjælpemidler","r":"Ved at nævne alt det, han ikke havde, viser forfatteren, hvor flot det var."},
{"l":4746,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken forkortelse betyder 'og så videre' og er skrevet rigtigt?","o":["os.v.","o.sv.","osv.","ov."],"a":"osv.","r":"Forkortelsen består af det første bogstav i hvert af de tre ord og får ét punktum til sidst."},
{"l":4765,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skolen har i år indført telefonfrie frikvarterer. Da vi spurgte elever og lærere, svarede Sofie fra 6.A: – Vi taler mere sammen. Kasper fra 7.B: – Det er barnligt. Lærer Tine: – Der er flere, der leger. Skolelederen mener, ordningen skal fortsætte, men vil evaluere den til sommer.' Hvorfor nævner artiklen både Sofie og Kasper?","o":["For at vise, at ældre elever er imod ordningen","For at vise, at eleverne er helt enige","Fordi de to har indført ordningen selv","For at vise, at eleverne er uenige"],"a":"For at vise, at eleverne er uenige","r":"Sofie er positiv, og Kasper er negativ. Artiklen vil vise begge sider."},
{"l":4784,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord i sætningen skal have stort begyndelsesbogstav: 'I påsken tager vi med den svenske færge til bornholm for at se Hammershus.'?","o":["bornholm","påsken","svenske","færge"],"a":"bornholm","r":"Bornholm er et stednavn og får stort. Højtider som påske og tillægsord som 'svenske' skrives med lille."},
{"l":4802,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvordan staves ordet her? 'Den nye lærer er en meget ___ mand, som alle kan lide.'","o":["simpatisk","sympatisk","sympatis","sympattisk"],"a":"sympatisk","r":"Ordet begynder med sym- med y, har ét t inde i ordet og ender på -isk."},
{"l":4822,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Asta er 'nøjeregnende', når hun bager. Hvad betyder det?","o":["hun bager altid meget store kager","hun regner tit forkert i opskriften","hun gør alting meget præcist","hun bager kun, når andre beder om det"],"a":"hun gør alting meget præcist","r":"Den, der er nøjeregnende, tager det meget nøje. Asta måler alt op og vil have det helt rigtigt."},
{"l":4841,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Lillesøster er tre år. Hvordan skrives ordet rigtigt: 'Min lillesøster er en ___ pige.'?","o":["3 årig","3'årig","3.årig","3-årig"],"a":"3-årig","r":"Når et tal bliver sat sammen med et ord, skriver man bindestreg imellem."},
{"l":4861,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find ledsætningen: 'Drengen, der vandt løbet, går i min klasse.'","o":["der vandt løbet","Drengen","går i min klasse","Drengen går i min klasse"],"a":"der vandt løbet","r":"Ledsætningen står inde i hovedsætningen og fortæller, hvilken dreng det er."},
{"l":4882,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rådyr i danske skove er gode til at gemme sig, så man ser dem sjældent. Det betyder ikke, at de er få. Når man opgør bestanden, tæller man derfor ikke dyrene direkte. I stedet tæller man for eksempel spor og det, jægerne nedlægger, og regner sig frem.' Hvad kan man slutte om tallene for bestanden?","o":["At de er helt nøjagtige ned til det sidste dyr","At de er et godt gæt og ikke et præcist tal","At de viser, at der er meget få rådyr i Danmark","At de kun gælder for rådyr i de nordlige skove"],"a":"At de er et godt gæt og ikke et præcist tal","r":"Når man 'regner sig frem' ud fra spor, er tallet et godt gæt og ikke en optælling."},
{"l":4898,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har kommaet på rette sted, når to hovedsætninger bindes sammen med 'men'?","o":["Jeg vil gerne med men, jeg skal først lave lektier.","Jeg vil, gerne med men jeg skal først lave lektier.","Jeg vil gerne med, men jeg skal først lave lektier.","Jeg vil gerne, med men jeg skal først lave lektier."],"a":"Jeg vil gerne med, men jeg skal først lave lektier.","r":"Kommaet står mellem de to hovedsætninger og dermed foran 'men', ikke efter."},
{"l":4917,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvordan skrives fem tusind to hundrede rigtigt i en artikel om en fodboldkamp?","o":["5,200 tilskuere","5:200 tilskuere","5'200 tilskuere","5.200 tilskuere"],"a":"5.200 tilskuere","r":"Tusinder kan adskilles med punktum. Med komma ville tallet blive et decimaltal lidt over fem."},
{"l":4937,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Trinnene kom nærmere. Ét. To. Tre. Så blev der stille.' Hvordan skaber forfatteren spænding?","o":["Med korte sætninger og en pludselig stilhed","Med lange sætninger, der bygger op til stilheden","Med en fortæller, der siger, at han er bange","Med ord, der rimer på hinanden"],"a":"Med korte sætninger og en pludselig stilhed","r":"Korte sætninger giver tempo, næsten som hjertebanken. Stilheden bagefter får læseren til at holde vejret."},
{"l":4958,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Læren om ordklasser og bøjning har et bestemt navn. Hvordan staves det?","o":["gramatik","grammatik","grammatikk","gramattik"],"a":"grammatik","r":"Ordet har dobbelt m, ét t og ét k til sidst."},
{"l":4980,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Emnet er et 'tabu' i familien. Hvad betyder det?","o":["det er noget, man taler om hver dag","det er noget, alle synes er sjovt","det er noget, man ikke taler om","det er noget, alle i familien er stolte af"],"a":"det er noget, man ikke taler om","r":"Tabu er et låneord fra et sprog i Stillehavet og betegner noget forbudt. I dag bruges det især om emner, man undgår."},
{"l":4995,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'statistik'?","o":["en person, der står stille i baggrunden af en film","en regel for, hvordan man bygger høje huse","en bog om Danmarks historie gennem tiden","tal, der er samlet og ordnet for at vise noget"],"a":"tal, der er samlet og ordnet for at vise noget","r":"Statistik bruges til at se mønstre i store mængder tal. Pas på: En statist er noget andet, nemlig en person i baggrunden."},
{"l":5012,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord kræver reglerne komma: 'Det hus hvor min bedstemor bor er over hundrede år gammelt.'?","o":["bor","bedstemor","er","gammelt"],"a":"bor","r":"Ledsætningen 'hvor min bedstemor bor' slutter efter 'bor', og efter en ledsætning skal der komma."},
{"l":5032,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en politiker, der 'dementerer' en historie i pressen?","o":["bekræfter, at den er sand","afviser, at den er sand","gør den længere og bedre","fortæller den for første gang"],"a":"afviser, at den er sand","r":"Et dementi er en officiel afvisning. Man siger offentligt, at en oplysning er forkert."},
{"l":5052,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Med røntgenstråler kan man se igennem kroppen. Det blev opdaget ved et tilfælde af en tysk fysiker i 1895, da han arbejdede med elektricitet. Han så, at noget lyste, hvor der ikke burde være noget lys. Han undersøgte det og fik et billede af knoglerne i sin kones hånd.' Hvad gjorde fysikeren, da han så noget uventet?","o":["Han stoppede forsøget af frygt for strålerne","Han arbejdede videre med elektricitet i stedet","Han undersøgte det i stedet for at overse det","Han gav opdagelsen videre til en anden forsker"],"a":"Han undersøgte det i stedet for at overse det","r":"Der står, at han undersøgte fænomenet. Tilfældet blev først til en opdagelse, fordi han var nysgerrig."},
{"l":5070,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at le': 'I aftes ___ publikum højt ad klovnen.'","o":["ler","leet","le","lo"],"a":"lo","r":"'At le' har en meget kort datid: 'lo'. 'Leet' er tillægsformen, der bruges efter 'har'."},
{"l":5092,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord mangler? 'Hun er så ___, at hun tror på alt, hvad folk fortæller.'","o":["godtroende","mistroisk","snarrådig","ærgerrig"],"a":"godtroende","r":"En godtroende person tror let på andre og kan derfor nemt blive snydt. 'Mistroisk' er det modsatte."},
{"l":5112,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Annoncen lover: Vores juice er 100 procent naturlig! Det lyder sundt. Men sukker er også naturligt, og juicen indeholder lige så meget af det som sodavand. Ordet naturlig siger altså ikke noget om, hvor sundt noget er. Det er den slags ord, man skal læse to gange.' Hvorfor skal man læse ordet to gange?","o":["Fordi ordet betyder, at der ikke er sukker i juicen","Fordi ordet kan få varen til at lyde sundere, end den er","Fordi ordet viser, at juicen er usund for alle børn","Fordi ordet ikke må bruges i en annonce om sodavand"],"a":"Fordi ordet kan få varen til at lyde sundere, end den er","r":"Teksten viser, at 'naturlig' lyder godt uden at sige noget om sundheden. Man kan let blive vildledt."},
{"l":5130,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Kommunen laver en 'kampagne' for cykelhjelme. Hvad er det?","o":["en lov om, at alle skal bruge det samme","en konkurrence med præmier til de bedste","en indsats for at få mange til at gøre noget","et forbud mod at cykle uden for byen"],"a":"en indsats for at få mange til at gøre noget","r":"En kampagne samler plakater, reklamer og lignende for at få mange til at gøre eller mene noget bestemt."},
{"l":5150,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hendes ord stak som nåle.' Hvad vil forfatteren sige?","o":["Hun talte meget lavt","Hun syede, mens hun talte","Hun havde glemt sine ord","Hendes ord gjorde ondt"],"a":"Hendes ord gjorde ondt","r":"Sammenligningen med nåle viser, at ordene føltes skarpe og sårede. Ord kan ikke stikke i virkeligheden, så det er et sprogligt billede."},
{"l":5168,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find subjektet: 'Vores nye nabo spiller trommer.'","o":["Vores nye nabo","spiller","trommer","spiller trommer"],"a":"Vores nye nabo","r":"Subjekt er det latinske navn for grundled. Spørg: Hvem spiller?"},
{"l":5190,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find det direkte objekt: 'Forældrene gav børnene en hund.'","o":["børnene","en hund","Forældrene","gav"],"a":"en hund","r":"Direkte objekt er det samme som genstandsled. Spørg: Hvad gav forældrene? 'Børnene' er indirekte objekt."},
{"l":5210,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Elevrådet ___ skolefesten i år.'","o":["organisere","organisserer","organiserer","organiseret"],"a":"organiserer","r":"Ordet har ét s, og nutid ender på -erer."},
{"l":5227,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I debatten om 'overvågning' tales der om kameraer på gaden. Hvad er det?","o":["at vågne tidligt om morgenen","at gøre vejene rene om natten","at sørge for lys på gaderne","at holde øje med, hvad folk gør"],"a":"at holde øje med, hvad folk gør","r":"Overvågning er, at nogen følger med i, hvad der foregår, for eksempel med kameraer eller over nettet."},
{"l":5246,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det gamle ord er: Af skade bliver man klog. Men er det sandt? Mange begår den samme fejl igen og igen. Det, der gør en klog, er ikke selve skaden, men at man stopper op og tænker over, hvad der gik galt. Ellers er skaden bare en skade.' Hvad er forfatterens tilføjelse til ordsproget?","o":["At man skal tænke over sin fejl for at lære af den","At man aldrig kan lære noget af en fejl","At fejl kun er gode, når andre begår dem","At man skal undgå alle fejl i sit liv, hvis man vil være klog"],"a":"At man skal tænke over sin fejl for at lære af den","r":"Forfatteren siger, at skaden ikke er nok. Det er eftertanken, der giver klogskab."},
{"l":5270,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Et smil eller en rynket pande er et ___. Hvordan staves ordet?","o":["ansigtudtryk","ansigtsudtryk","ansigsudtryk","ansidsudtryk"],"a":"ansigtsudtryk","r":"Ordet har gt i 'ansigt' og fuge-s foran 'udtryk'."},
{"l":5289,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken slags stedord er 'dette' i: 'Dette billede malede jeg selv.'","o":["ubestemt stedord","ejestedord","påpegende stedord","spørgende stedord"],"a":"påpegende stedord","r":"'Dette' peger på et bestemt billede, ligesom hvis man viste det med en finger."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Min storebror er den slags menneske, der kan finde alt, undtagen opvaskemaskinen.' Hvad siger skribenten egentlig om sin bror?","o":["At han har dårligt syn og tit farer vild","At han er god til at holde orden i køkkenet","At han har mistet nøglen til opvaskemaskinen","At han ikke tager sin del af opvasken"],"a":"At han ikke tager sin del af opvasken","r":"Broren kan selvfølgelig godt finde maskinen. Det er en spøg med, at han undgår den, altså at han slipper for arbejdet."},
{"l":5317,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord giver mening? 'Efter skandalen var firmaets ___ i bund, og ingen ville handle der.'","o":["omdømme","retning","overblik","inventar"],"a":"omdømme","r":"Et omdømme er det, andre mener om en. Et dårligt omdømme kan betyde, at kunderne bliver væk."},
{"l":5336,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Aftenen før skakfinalen lå jeg og tænkte på alt det, der kunne gå galt. Storesøster satte sig på sengekanten og spurgte, om jeg kunne huske dengang, jeg tabte til en seksårig. Jeg kom til at grine. Da hun var gået, faldt jeg i søvn.' Hvorfor spørger storesøster om det gamle nederlag?","o":["Hun vil advare fortælleren mod at undervurdere små modstandere","Hun vil have fortælleren til at grine og slappe af","Hun vil minde fortælleren om, at der skal øves noget mere","Hun vil vise fortælleren, at finalen næppe kan vindes i morgen"],"a":"Hun vil have fortælleren til at grine og slappe af","r":"Et sjovt minde får latteren og roen frem hos en nervøs fortæller. En advarsel kunne passe til nederlaget, men fortælleren er bekymret nok og falder jo i søvn bagefter."},
{"l":5355,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at forsvinde': 'Vi fandt den ___ kat på loftet.'","o":["forsvundet","forsvandt","forsvundne","forsvinder"],"a":"forsvundne","r":"Efter 'den' foran et navneord står tillægsformen i bestemt form. Af 'forsvundet' bliver det 'forsvundne'."},
{"l":5377,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sofie er 'ambivalent' over for flytningen. Hvordan har hun det?","o":["hun er helt sikker i sin sag","hun er ligeglad med det hele","hun er i rigtig godt humør","hun har blandede følelser"],"a":"hun har blandede følelser","r":"'Ambi-' betyder begge. Den, der er ambivalent, trækkes i to retninger og føler både for og imod."},
{"l":5396,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Prøven var i gang, og der var helt stille i lokalet. Det store ur på væggen tikkede højere og højere. Sofus kiggede op på det for femte gang og havde stadig kun skrevet sit navn.' Hvad viser det, at uret tikker højere og højere?","o":["At Sofus er bange for ikke at nå det","At uret er ved at gå i stykker","At Sofus er blevet træt af at sidde ned","At tiden snart er gået for alle i lokalet"],"a":"At Sofus er bange for ikke at nå det","r":"Et ur tikker ikke rigtig højere. Men Sofus kigger hele tiden på det, for tiden går, og han har kun skrevet sit navn."},
{"l":5414,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er rytme i et digt?","o":["Antallet af ord, linjer og strofer i hele digtet","Den takt, man hører, når nogle stavelser får tryk","Den måde, linjerne er sat op på siden","De ord, der lyder ens sidst i linjerne"],"a":"Den takt, man hører, når nogle stavelser får tryk","r":"Rytmen opstår, når stavelser med og uden tryk skifter. Det er derfor, man næsten kan klappe takten til et digt."},
{"l":5432,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bogens hovedperson bor i et land, hvor alle får de samme karakterer. Ingen får lov at skille sig ud. Det virker først fredeligt. Men efterhånden opdager hun, at ingen længere prøver at gøre noget godt, for det gør ingen forskel. Forfatteren lader os selv afgøre, om det er en drøm eller et mareridt.' Hvad gør forfatteren ifølge teksten?","o":["Giver et klart svar på, om landet er godt eller dårligt","Forklarer, hvordan karakterer bør gives i skolen","Lader læseren selv afgøre det","Beskriver sin egen skoletid i et fremmed land"],"a":"Lader læseren selv afgøre det","r":"Sidste sætning siger, at læseren selv må afgøre det. Forfatteren giver ikke et færdigt svar."},
{"l":5453,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'retorik'?","o":["kunsten at huske lange tekster","læren om sprogenes historie","læren om at skrive pænt i hånden","kunsten at tale overbevisende"],"a":"kunsten at tale overbevisende","r":"Retorik stammer fra antikkens Grækenland, hvor talere øvede sig i at påvirke tilhørerne."},
{"l":5474,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Broen er en flot ___ af stål.'","o":["konstruktion","konstruksion","konstrution","kunstruktion"],"a":"konstruktion","r":"Ordet begynder med kon og ender på -ktion."},
{"l":5492,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Karen havde gået på gymnastikhold i otte år. Nu sagde hun til træneren, at hun ville stoppe. Træneren spurgte hvorfor. Karen kiggede på de nye, små piger, der kæmpede med spring, hun selv kunne i søvne. – Jeg har glemt, hvorfor jeg begyndte, sagde hun.' Hvad er Karens problem?","o":["Hun er blevet for dårlig til gymnastik","Hun har mistet glæden ved at gå til gymnastik","Hun er blevet uvenner med træneren på gymnastikholdet","Hun er bange for de nye, små piger"],"a":"Hun har mistet glæden ved at gå til gymnastik","r":"Hun kan alle springene, men hun kan ikke længere mærke, hvorfor hun gør det. Det er ikke sjovt mere."},
{"l":5510,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Bagerens ___ er kanelsnegle.'","o":["spesialitet","specialitæt","specialitet","specielitet"],"a":"specialitet","r":"S-lyden skrives med c, der er a efter i, og ordet ender på -itet."},
{"l":5531,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'meget' i: 'Det er meget koldt i dag.'","o":["stedord","talord","tillægsord","biord"],"a":"biord","r":"'Meget' siger her, hvor koldt det er, og står til tillægsordet 'koldt'. Så er det et biord."},
{"l":5552,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da jeg fortalte min bedste ven, at mine forældre skulle skilles, sagde hun: Det ved jeg ikke, hvad jeg skal sige til. Så satte hun sig ved siden af mig. Mange voksne har sagt kloge ting til mig siden hen. Jeg kan ikke huske en eneste af dem. Jeg kan huske, at hun satte sig.' Hvad har betydet mest for fortælleren?","o":["At vennen satte sig ved siden af","De kloge ting, de voksne har sagt","At forældrene blev gode venner bagefter","At vennen havde gode råd om skilsmisse"],"a":"At vennen satte sig ved siden af","r":"Vennen vidste ikke, hvad hun skulle sige, men hun satte sig. Det husker fortælleren, mens de voksnes kloge ord er glemt."},
{"l":5572,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Biblioteket i Toftby vil afskaffe bøderne for bøger, der afleveres for sent. Bibliotekaren siger, at nogle børn holder op med at komme, fordi de ikke tør vise sig med en bøde. Et bibliotek i en anden kommune har afskaffet bøderne og fået flere bøger tilbage, ikke færre.' Hvad er det overraskende i oplysningen om den anden kommune?","o":["At bøderne der var højere end i Toftby","At det gav flere tilbageleverede bøger, ikke færre","At færre bøder gav færre besøgende på biblioteket","At børn i den kommune aldrig afleverer for sent"],"a":"At det gav flere tilbageleverede bøger, ikke færre","r":"Man ville tro, at uden bøder kom færre bøger tilbage. Det modsatte skete, og det støtter forslaget."},
{"l":5592,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mit første job var at samle indkøbsvogne på en parkeringsplads. Min chef sagde: Det handler om vognene. Men jeg opdagede hurtigt, at det handlede om alt det andet. Om at møde til tiden. Om at sige goddag. Om at holde ud, når det regnede. Jeg har aldrig siden lært så meget på så kort tid.' Hvad har fortælleren fået ud af jobbet?","o":["Evnen til at samle vogne hurtigere end andre","Større viden om, hvordan parkeringspladser bliver lavet","Gode vaner som at møde til tiden og holde ud","Mange penge, som senere blev brugt på uddannelse"],"a":"Gode vaner som at møde til tiden og holde ud","r":"Fortælleren nævner mødetider, høflighed og udholdenhed. Det er mere end selve arbejdet med vognene."},
{"l":5608,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Hvis vi var gået tidligere, ___ vi have nået bussen.'","o":["vil","har","havde","ville"],"a":"ville","r":"Det er tænkt og ikke sket. Efter 'hvis' med førdatid bruger man her 'ville have' plus tillægsform."},
{"l":5630,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg det rigtige udsagnsled: 'Da vi ___ i Norge sidste sommer, så vi en elg.'","o":["var","har været","er","bliver"],"a":"var","r":"'Sidste sommer' er et afsluttet tidspunkt, og så skal der bruges datid. Førnutid passer ikke sammen med et bestemt tidspunkt i fortiden."},
{"l":5651,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken fortællesamling er 'Aladdin' kendt fra?","o":["Grimms eventyr","Tusind og én nat","Æsops fabler","Islandske sagaer"],"a":"Tusind og én nat","r":"'Tusind og én nat' er en stor samling fortællinger fra Mellemøsten. Her finder man også historien om Ali Baba."},
{"l":5671,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad forstår man ved 'hykleri'?","o":["at sige noget sandt på en uvenlig måde","at sige ja uden at vide, hvad det handler om","at sige ét og selv gøre noget andet","at sige mere, end man har lov til"],"a":"at sige ét og selv gøre noget andet","r":"En hykler lader, som om han er bedre, end han er. Ordene passer ikke med handlingerne."},
{"l":5690,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Tør munden med en ___. Hvordan staves ordet?","o":["servjet","serviett","sørviet","serviet"],"a":"serviet","r":"Ordet har i efter v, og det slutter på ét t."},
{"l":5714,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hunden bliver ___, når vi klapper katten.'","o":["jaloux","jalu","jalous","jaluks"],"a":"jaloux","r":"Ordet er fransk og ender på -oux. X'et høres ikke."},
{"l":5731,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I et forsøg skal eleverne gøre 'observationer'. Hvad skal de gøre?","o":["gætte på, hvad der vil ske bagefter","se godt efter og skrive ned, hvad der sker","læse om forsøget i en bog","købe det rigtige udstyr til forsøget"],"a":"se godt efter og skrive ned, hvad der sker","r":"En observation er noget, man selv har set. Man ser efter, hvad der faktisk sker, i stedet for at gætte."},
{"l":5749,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mejsekassen hang på æbletræet hele vinteren uden at blive brugt. I april fløj en fugl ind og ud af hullet med små strå i næbbet. Et par uger senere kom den i stedet med larver i næbbet, mange gange i timen.' Hvad er der sket inde i kassen?","o":["Fuglen er stadig i gang med at bygge sin rede færdig.","En anden fugl er flyttet ind i kassen.","Der er kommet unger, som skal have mad.","Fuglen gemmer larver til næste vinter."],"a":"Der er kommet unger, som skal have mad.","r":"Strå bruger fuglen til at bygge rede. Når den bagefter flyver ind med larver mange gange i timen, er det mad, og så må der være unger i kassen."},
{"l":5771,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord står i bydeform: 'Hvis du hører noget, så sig det til den lærer, der har gårdvagt.'?","o":["hører","har","noget","sig"],"a":"sig","r":"'Sig' er her bydeform af 'sige', og det er ikke stedordet 'sig'. 'Hører' og 'har' er også udsagnsord, men de står i nutid."},
{"l":5793,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om taget på husene har rigtig kongruens?","o":["Taget på de røde huse er gammelt.","Taget på de røde huse er gamle.","Taget på de røde huse er gammel.","Tagene på det røde hus er gammelt."],"a":"Taget på de røde huse er gammelt.","r":"Grundleddet er 'taget', som er et intetkønsord i ental, så tillægsordet skal have -t. 'Huse' står kun i et forholdsordsled og bestemmer ikke bøjningen."},
{"l":5806,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En kilde vil være 'anonym' i en artikel. Hvad ønsker kilden?","o":["at læse artiklen før trykning","at få sit navn holdt hemmeligt","at få betaling for at udtale sig","at optræde med billede i avisen"],"a":"at få sit navn holdt hemmeligt","r":"Anonym betyder uden navn. Journalisten kender kilden, men læserne får ikke at vide, hvem det er."},
{"l":5826,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Min søster siger, at lektier er spild af tid, fordi hun aldrig har brugt dem til noget. Hun er 13 år.' Hvad vil skribenten antyde med den sidste sætning?","o":["At søsteren burde have færre lektier","At søsteren er ældre, end man skulle tro","At søsteren er for ung til at kunne vide det","At søsteren ved lige så meget som voksne"],"a":"At søsteren er for ung til at kunne vide det","r":"Hun er kun 13 år. Så har hun ikke levet længe nok til at vide, hvad hun får brug for senere."},
{"l":5848,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Alle flyttekasserne var mærket med fars pæne skrift: KØKKEN, BAD, STUE. På den sidste stod der bare: Liv. Hun satte sig på den og så ud ad vinduet på en gade, hun ikke kendte navnet på.' Hvordan har Liv det sandsynligvis?","o":["Hun glæder sig til at pakke kasserne ud","Hun er vred på sin far over hans skrift","Hun er stolt af at have sin egen kasse","Hun føler sig fremmed på det nye sted"],"a":"Hun føler sig fremmed på det nye sted","r":"Hun sidder stille på kassen og kigger på en gade, hun ikke engang kender navnet på. Hun føler sig ikke hjemme endnu."},
{"l":5869,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Tænk på den lille hund, der sidder alene og fryser i et bur. Den har kun dig.' Hvilken appelform er der her?","o":["patos","hjemmel","logos","etos"],"a":"patos","r":"Teksten vil vække medlidenhed hos læseren. Når afsenderen appellerer til følelser, er det patos."},
{"l":5888,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I et brev står der: 'Arbejdet påbegyndes mandag.' Hvad sker der mandag?","o":["arbejdet bliver afsluttet","arbejdet går i gang","arbejdet bliver aflyst","arbejdet bliver betalt"],"a":"arbejdet går i gang","r":"'Påbegynde' er et formelt ord for at begynde. Forstavelsen 'på-' ændrer ikke på meningen, men gør sproget mere højtideligt."},
{"l":5903,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det latinske navn for bydeform?","o":["infinitiv","indikativ","imperativ","participium"],"a":"imperativ","r":"Bydeform hedder imperativ. Infinitiv er navneform, og participium er tillægsform."},
{"l":5925,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Farfar lagde båden op i år, længe før frosten kom. – Knæet, sagde han og så væk. Vi har aldrig før været færdige før november. Jeg foldede sejlet sammen uden at spørge om mere.' Hvad forstår fortælleren sandsynligvis?","o":["At farfar er bange for frosten i november","At farfar vil købe en større båd til næste år","At farfar er sur over, at sejlet er foldet forkert","At farfar snart ikke kan klare at sejle mere"],"a":"At farfar snart ikke kan klare at sejle mere","r":"Farfar stopper tidligere, end de nogensinde har gjort, siger kun 'Knæet' og ser væk. Fortælleren forstår det og spørger ikke om mere, for det er svært at tale om."},
{"l":5947,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Overskrift i skolebladet: Elever fra 8. klasse underviser ældre i at bruge tablet.' Hvorfor er overskriften tvetydig?","o":["'Ældre' kan betyde både gamle folk og større elever","'Underviser' kan betyde både hjælper og driller","'Bruge' kan betyde både anvende og købe","'8. klasse' kan betyde både skole og hold"],"a":"'Ældre' kan betyde både gamle folk og større elever","r":"Teksten kan læses, så det er ældre mennesker, eller så det er elever, der er ældre end 8. klasse. Det er ordet 'ældre', der giver tvivlen."},
{"l":5969,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om den lange tur har rigtig kongruens i tal?","o":["Hver af eleverne var sultne efter turen.","Hver af eleverne var sulten efter turen.","Hver af eleverne var sultent efter turen.","Eleverne var sulten efter turen."],"a":"Hver af eleverne var sulten efter turen.","r":"Grundleddet er 'hver', som står i ental, så tillægsordet skal også stå i ental. Lad dig ikke snyde af flertalsordet 'eleverne' lige efter."},
{"l":5988,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Bølgerne kom. Bølgerne gik. Bølgerne blev ved hele natten.' Hvilket virkemiddel bruger forfatteren?","o":["metafor","sammenligning","gentagelse","ironi"],"a":"gentagelse","r":"Ordet 'bølgerne' gentages i starten af hver sætning. Gentagelsen gør, at man næsten kan mærke, hvordan de bliver ved og ved."},
{"l":6000,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tillykke til skolen med det nye cykelskur. Det ser ud til at ville holde helt til den første vind.' Hvad er skribentens vurdering?","o":["Skuret er solidt og gennemtænkt","Skuret er blevet alt for stort","Skolen fortjener ros for skuret","Skuret holder næppe ret længe"],"a":"Skuret holder næppe ret længe","r":"Lykønskningen er ironisk. 'Helt til den første vind' er en spydig måde at sige, at skuret ikke holder længe."},
{"l":6019,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige tillægsform: 'Huset havde stået ___ i mange år.'","o":["forladt","forlat","forladet","forlagt"],"a":"forladt","r":"Tillægsformen af 'forlade' ender på -dt. 'Forlagt' betyder, at man har lagt noget et forkert sted."},
{"l":6039,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Sofie var genert og meget klog.' Hvilken type personkarakteristik er det?","o":["Indirekte karakteristik","Direkte karakteristik","Miljøbeskrivelse","Naturbeskrivelse"],"a":"Direkte karakteristik","r":"Fortælleren siger ligeud, hvordan Sofie er. Når personens egenskaber nævnes direkte, er det direkte karakteristik."},
{"l":6060,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Alle som har glemt deres idrætstøj må sidde på bænken.'?","o":["glemt","må","idrætstøj","sidde"],"a":"idrætstøj","r":"Ledsætningen 'som har glemt deres idrætstøj' slutter efter 'idrætstøj', og så fortsætter hovedsætningen."},
{"l":6080,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord har fået stort med urette: 'Vi fejrer Påske, og på Kristi himmelfartsdag besøger vi Yusufs mormor ved Limfjorden.'?","o":["Yusufs","Limfjorden","Kristi","Påske"],"a":"Påske","r":"Højtider som jul og påske skrives med lille. 'Kristi' er et navn og beholder det store bogstav."},
{"l":6100,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning bruger kolon rigtigt til at give en forklaring på, at planen gik galt?","o":["Planen mislykkedes af én grund: Ingen havde husket nøglen.","Planen: mislykkedes af én grund ingen havde husket nøglen.","Planen mislykkedes af: én grund ingen havde husket nøglen.","Planen mislykkedes af én: grund ingen havde husket nøglen."],"a":"Planen mislykkedes af én grund: Ingen havde husket nøglen.","r":"Kolon står, når første del er sluttet og lægger op til en forklaring. Her fortæller anden del, hvad grunden var."},
{"l":6113,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Flot vejr!' siger Mads, mens regnen vælter ned. Hvilket sprogligt virkemiddel bruger han?","o":["allitteration","ironi","besjæling","sammenligning"],"a":"ironi","r":"Ved ironi siger man det modsatte af det, man mener. Situationen viser, at Mads slet ikke synes, at vejret er flot."},
{"l":6136,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Vand består af 'molekyler'. Hvad er et molekyle?","o":["en blanding af væske og gas","en celle, der kan dele sig","en gruppe atomer, der er bundet sammen","en lille dråbe af et helt rent stof"],"a":"en gruppe atomer, der er bundet sammen","r":"Et vandmolekyle består af to brintatomer og et iltatom. En dråbe vand indeholder et enormt antal molekyler."},
{"l":6156,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elevrådet vil have længere frikvarterer. Skolelederen svarer, at så må skoledagen blive længere. Elevrådet spørger så, om man ikke i stedet kan afkorte morgensamlingen.' Hvad går elevrådets sidste forslag ud på?","o":["At afskaffe alle frikvarterer på skolen","At gøre skoledagen længere for alle elever","At lade skolelederen vælge en løsning","At skaffe tiden uden at forlænge skoledagen"],"a":"At skaffe tiden uden at forlænge skoledagen","r":"Elevrådet accepterer, at tiden skal findes et sted, men peger på morgensamlingen, så skoledagen ikke bliver længere."},
{"l":6175,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Dyrlægen fortalte om de ___, som kaniner kan få.'","o":["sygdomme","sygdome","sykdomme","sygdomer"],"a":"sygdomme","r":"Ental hedder 'sygdom' med ét m, men i flertal bliver m'et dobbelt."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vi så nordlys i nordnorge og kørte videre til Sverige.'?","o":["nordlys","nordnorge","kørte","videre"],"a":"nordnorge","r":"Nordnorge er navnet på en landsdel. Nordlys er et naturfænomen og skrives med lille."},
{"l":6209,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Skolen bør have mere idræt, fordi eleverne bliver bedre til at koncentrere sig af at bevæge sig.' Hvad er belægget?","o":["At skolen bør have mere idræt, end den har i dag","At det er vigtigt, at eleverne kan koncentrere sig","At eleverne koncentrerer sig bedre, når de bevæger sig","At elever skal have lov til at bevæge sig i timerne"],"a":"At eleverne koncentrerer sig bedre, når de bevæger sig","r":"Belægget er begrundelsen for påstanden, og her står den efter 'fordi'. At skolen bør have mere idræt, er selve påstanden."},
{"l":6226,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren spørger Sofie, om hun er 'faldet i staver'. Hvad mener læreren?","o":["om hun har lavet mange fejl i diktaten","om hun er snublet over noget på gulvet","om hun er blevet skræmt af noget","om hun er helt væk i sine tanker"],"a":"om hun er helt væk i sine tanker","r":"Talemåden har intet med stavning at gøre. Staver er her de træstykker, en tønde er bygget af."},
{"l":6247,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Der hænger et ___ flag i klassen.'?","o":["dansk","danskt","danske","danskere"],"a":"dansk","r":"Tillægsord for nationalitet på -sk får ikke -t i intetkøn. Derfor hedder det 'et dansk flag'."},
{"l":6269,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om lærerens stile står i aktiv?","o":["Stilene rettes af læreren.","Stilene fylder hele lærerens taske.","Stilene bliver rettet af læreren.","Stilene blev rettet af læreren."],"a":"Stilene fylder hele lærerens taske.","r":"I aktiv gør grundleddet selv noget: Stilene fylder tasken. I de tre andre sætninger er det læreren, der handler, og der sker noget med stilene, så de står i passiv."},
{"l":6293,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I naturfag lærer man om 'vandets kredsløb'. Hvad beskriver det?","o":["vandets vej gennem rørene i et hus","havets stigning og fald ved højvande","vandets vej mellem hav, luft og land","blodets vej rundt i kroppen"],"a":"vandets vej mellem hav, luft og land","r":"Vand fordamper, bliver til skyer, falder som nedbør og løber tilbage til havet. Så begynder det hele forfra."},
{"l":6301,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det latinske navn for omsagnsled?","o":["subjekt","adverbial","objekt","prædikativ"],"a":"prædikativ","r":"Omsagnsled hedder prædikativ. Subjekt er grundled, og objekt er genstandsled eller hensynsled."},
{"l":6321,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvis vi først tillader kasketter i klassen, så kommer der snart også hættetrøjer, høretelefoner og snacks, og til sidst gør eleverne bare, hvad de vil.' Hvad er svagheden i denne tankegang?","o":["Den viser ikke, at kasketter fører til alt det andet","Den siger ikke, hvem der har bestemt reglen","Den tager ikke stilling til, om kasketter bør tillades","Den giver for mange eksempler på noget forbudt"],"a":"Den viser ikke, at kasketter fører til alt det andet","r":"Det kaldes et glidebaneargument: Man siger, at en lille ændring ender i kaos, men man giver ingen grund til, at det skulle ske."},
{"l":6344,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Det er ikke ___ at bruge mobil i timerne.'","o":["tilladet","tilladt","tillat","tilat"],"a":"tilladt","r":"Ordet består af 'til' og 'ladt', og derfor er der dobbelt-l. Tillægsformen af 'tillade' ender på -dt."},
{"l":6362,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Haren lagde sig til at sove midt i løbet, fordi den var sikker på at vinde. Skildpadden gik langsomt videre og kom først over målstregen.' Hvad er fablens moral?","o":["Den, der er hurtigst, vinder altid til sidst","Man skal aldrig løbe om kap med dem, der er langsommere","Den, der bliver ved, kan slå den, der er for selvsikker","Man skal hvile sig godt, før man skal noget vigtigt"],"a":"Den, der bliver ved, kan slå den, der er for selvsikker","r":"Skildpadden bliver ved med at gå. Haren taber ikke, fordi den er langsom, men fordi den er for sikker på sig selv."},
{"l":6383,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Historien lød ___, så ingen rigtig troede på den.'","o":["tvilsom","tvivlsomm","tvivlsum","tvivlsom"],"a":"tvivlsom","r":"Ordet kommer af 'tvivl', så v'et skal med foran l. Endelsen -som har kun ét m."},
{"l":6400,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Alle klubberne omkring os har fået kunstgræsbane. Så må vi jo også have en.' Hvad er problemet med begrundelsen?","o":["At andre gør noget, siger ikke, at det er rigtigt her","At ikke alle klubber har råd til en kunstgræsbane","At de andre klubber ikke vil betale for banen","At kunstgræs slides hurtigere end almindeligt græs"],"a":"At andre gør noget, siger ikke, at det er rigtigt her","r":"Det kaldes at hoppe med på vognen. Argumentet henviser til, hvad alle andre gør, men siger ikke, hvorfor det er en god idé."},
{"l":6422,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Hun vil gerne tage en ___ som tømrer.'","o":["udannelse","uddannelse","uddanelse","uddannelsse"],"a":"uddannelse","r":"Ordet består af 'ud' og 'dannelse', og derfor er der både dobbelt-d og dobbelt-n."},
{"l":6443,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Hun besidder stor viden om fugle.' Hvilket hverdagsord kan erstatte 'besidder'?","o":["søger","mangler","har","skjuler"],"a":"har","r":"'Besidde' er et højtideligt ord for at have eller eje. Det bruges både om ting og om evner og viden."},
{"l":6464,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Overskrift i lokalavisen: Forældre kræver ro i klassen. I artiklen står der, at tre forældre har skrevet til skolen om uroen i 7.b. Skolen har i alt 900 forældre.' Hvad er problemet med overskriften?","o":["Den fortæller ikke, hvilken klasse der er tale om","Den siger, at alle 900 forældre har skrevet","Den handler om klassen og ikke om forældrene","Den får det til at lyde, som om det gælder mange"],"a":"Den får det til at lyde, som om det gælder mange","r":"'Forældre' uden tal lyder som en stor gruppe, men det er tre ud af 900. Overskriften gør sagen større, end den er."},
{"l":6487,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Ida er rolig, og hendes bror har en helt anden ___.'","o":["personlighed","personlihed","persolighed","perssonlighed"],"a":"personlighed","r":"Ordet kommer af 'personlig' og '-hed'. Det stumme g skal med, og der er ét s."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forslaget om et nyt cykelskur kan vi roligt se bort fra. Hende, der stiller det, kommer jo altid for sent til møderne.' Hvad er der galt med argumentet?","o":["Det stiller for mange krav til mødedeltagerne","Det angriber personen i stedet for forslaget","Det overser, at et cykelskur kan blive for dyrt","Det gentager det samme forslag to gange"],"a":"Det angriber personen i stedet for forslaget","r":"At komme for sent siger intet om, hvorvidt et cykelskur er en god idé. Det kaldes et personangreb."},
{"l":6518,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Hans forklaring var ikke ___, så vi troede ikke på ham.'","o":["troværdighed","troværdigt","troværdig","troen"],"a":"troværdig","r":"Ordet 'forklaring' er fælleskøn, så tillægsordet skal stå uden -t. 'Troværdighed' er et navneord og passer ikke efter 'var ikke'."},
{"l":6539,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord er stavet rigtigt? Det er sedlen fra lægen, som du viser på apoteket.","o":["resept","reccept","recebt","recept"],"a":"recept","r":"S-lyden skrives her med c, og ordet ender på -pt."},
{"l":6556,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Dollarens kurs steg i går.' Hvad betyder 'kurs' i denne sætning?","o":["hvad den koster i andre landes penge","den retning, et skib sejler i","undervisning over flere uger","antallet af sedler, der er trykt"],"a":"hvad den koster i andre landes penge","r":"Ordet 'kurs' har flere betydninger. Når man taler om penge, handler det om, hvor mange kroner en dollar koster."},
{"l":6578,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Risengrød skal have smør, sukker og ___.'","o":["kannel","kanel","kanell","kanæl"],"a":"kanel","r":"Ordet skrives med ét n og ét l."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
